def save():
    pending=out/"execution.pending.json"
    with pending.open("xb") as stream:
        stream.write((json.dumps(record,indent=2)+"\n").encode("utf-8"))
        stream.flush(); os.fsync(stream.fileno())
    pending.replace(out/"execution.json")

