try:
    save()
    record["source_before"]=snapshot()
    if not fixed(record["source_before"]): raise Rejected("fixed_source_before_differs")
    with inspector.open("xb") as stream:
        stream.write(raw); stream.flush(); os.fsync(stream.fileno())
    if inspector.read_bytes()!=raw: raise Rejected("materialized_inspector_differs")
    record["state"]="inspection-starting"; save()
    with stdout_path.open("xb") as stream:
        child=subprocess.Popen(command,cwd=out,env=env,stdout=stream,stderr=subprocess.DEVNULL)
        record["child_pid"]=child.pid
        record["state"]="inspection-running"; save()
        actual=child.wait()
        record["actual_returncode"]=actual
        record["original_process_complete"]=True
        stream.flush(); os.fsync(stream.fileno())
    stdout=file_record(stdout_path)
    record.update(stdout_bytes=stdout["bytes"],stdout_sha256=stdout["sha256"],stdout_complete=True)
    record["source_after"]=snapshot()
    record["state"]="inspection-returned"; save()
    if stdout["bytes"]>2097152: raise Rejected("inspector_output_size_contract_differs")
    observed=stdout_path.read_bytes()
    if len(observed)!=stdout["bytes"] or digest(observed)!=stdout["sha256"]: raise Rejected("inspector_output_changed_after_terminal")
    report=json.loads(observed)
    if report.get("schema")!="hepta.service-root01.safe-static-token-classification.v3" or report.get("target")!="/data/hepta-service-root-01.py" or report.get("assessment") not in ("unknown_static_purpose","static_original_root29_selector_declared") or report.get("ordinary_execution_authority_proven") is not False or report.get("runtime_owner_custody_observed") is not False or report.get("current_runtime_instance_observed") is not False:
        raise Rejected("fixed_inspection_output_contract_differs")
    status=report.get("status")
    if status not in ("ok","incomplete","rejected","unparseable","unavailable","unknown"): raise Rejected("inspection_status_contract_differs")
    record["inspection_status"]=status
    record["classification"]=report["assessment"]
    if not fixed(record["source_after"]): raise Rejected("fixed_source_after_differs")
    if actual==0 and status=="ok":
        record["state"]="inspection-recorded-static-classification"
        wrapper_code=0
    else:
        record["state"]="inspection-returned-nonzero-or-incomplete"
except BaseException as error:
    record["state"]="wrapper-failed-or-uncertain"
    record["error"]={"code":error.code} if isinstance(error,Rejected) else {"type":type(error).__name__}
    # No signal, wait retry, process cleanup, target execution or rerun follows.
finally:
    record["seconds"]=time.monotonic()-started
    record["wrapper_returncode"]=wrapper_code
    save()
execution=file_record(out/"execution.json")
print(json.dumps({"state":record["state"],"execution":str(out/"execution.json"),
                  "execution_bytes":execution["bytes"],"execution_sha256":execution["sha256"],
                  "actual_returncode":record["actual_returncode"],
                  "original_process_complete":record["original_process_complete"],
                  "classification":record["classification"]}),flush=True)
raise SystemExit(wrapper_code)
